import React from "react";
import { calculateReadingScore } from "../service/ReadingService";
import { readingRepo } from "../repo/readingRepo";
import ReadingPresenter from "../ui/ReadingPresenter";

export default function ReadingContainer() {
  const score = calculateReadingScore(readingRepo);
  return <ReadingPresenter score={score} />;
}
